// Writes CHANGELOG.md from the git tags: one section per release, newest
// first, with its known-PHP-version changes and its commits. Release notes on
// GitHub can be deleted; this file keeps the history.
//
//   npm run changelog
//
// Run it after bumping SharedAssembyInfo.cs and before tagging. HEAD then gets
// a section for that version, and the commit that carries CHANGELOG.md is the
// one to tag. If that version is already tagged, commits after the newest tag
// go under "Unreleased". Needs git and Node 18 or later.
import { writeFileSync } from "node:fs";
import { SOURCE, describeRowChanges, formatDate, parseRows, rowChanges } from "./php-versions.mjs";
import { FORK_BASE, UPSTREAM, UPSTREAM_TAG, fail, githubRepo, run, sourceVersion, upstreamCompareUrl } from "./repo.mjs";

const OUTPUT = "CHANGELOG.md";
const repo = githubRepo();
const url = `https://github.com/${repo}`;

const tags = run("git", ["tag", "--list", "v*", "--sort=v:refname"])
    .split("\n")
    .filter((t) => /^v\d+\.\d+\.\d+(\.\d+)?$/.test(t));

const releases = tags.map((tag) => ({ name: tag, ref: tag, date: run("git", ["log", "-1", "--format=%cs", tag]) }));
const newest = tags.at(-1) ?? FORK_BASE;
if (run("git", ["rev-list", "--count", `${newest}..HEAD`]) !== "0") {
    const next = `v${sourceVersion()}`;
    const today = new Date().toISOString().slice(0, 10);
    releases.push(tags.includes(next) ? { name: "Unreleased", ref: "HEAD", date: "" } : { name: next, ref: "HEAD", date: today });
}
if (releases.length === 0) fail("No v* tags and no commits after the fork. Nothing to write.");

const rowsAt = (ref) => {
    try {
        return parseRows(run("git", ["show", `${ref}:${SOURCE}`]));
    } catch (e) {
        fail(`${ref}: ${e.message}`);
    }
};
const escape = (text) => text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

const sections = releases.map((release, i) => {
    const previous = i === 0 ? FORK_BASE : releases[i - 1].ref;
    const previousName = i === 0 ? "the fork point" : releases[i - 1].name;
    const newRows = rowsAt(release.ref);
    const changes = describeRowChanges(rowChanges(rowsAt(previous), newRows), newRows);
    const commits = run("git", ["log", "--no-merges", "--format=%H%x09%s", `${previous}..${release.ref}`])
        .split("\n")
        .filter(Boolean)
        .map((line) => {
            const [sha, subject] = line.split("\t");
            return `- [\`${sha.slice(0, 7)}\`](${url}/commit/${sha}) ${escape(subject)}`;
        });

    const lines = [`## ${release.name}${release.date ? ` (${formatDate(release.date)})` : ""}`, ""];
    lines.push(...(changes.length > 0 ? changes : ["- No changes to the known PHP versions"]), "");
    if (commits.length > 0) {
        lines.push("<details>", `<summary>${commits.length} commit${commits.length === 1 ? "" : "s"}</summary>`, "", ...commits, "", "</details>", "");
    }
    // A section for HEAD has no tag on GitHub to compare against yet.
    if (release.ref !== "HEAD") {
        const base = i === 0 ? FORK_BASE.slice(0, 7) : releases[i - 1].ref;
        lines.push(`[Compare with ${previousName}](${url}/compare/${base}...${release.ref})`, "");
    }
    return lines.join("\n");
});

const latestRef = releases.at(-1).name === "Unreleased" ? "master" : releases.at(-1).name;
const text = `# Changelog

Releases of this fork of [${UPSTREAM}](https://github.com/${UPSTREAM}), newest first.
Upstream is archived, and its last release was ${UPSTREAM_TAG}.
[All changes since upstream ${UPSTREAM_TAG}](${upstreamCompareUrl(repo, latestRef)}).

Generated by \`npm run changelog\` from the git tags. Edit the script, not this file.

${sections.reverse().join("\n")}
## ${UPSTREAM_TAG} and earlier

See the [upstream releases](https://github.com/${UPSTREAM}/releases).
`;

writeFileSync(OUTPUT, text);
console.log(`Wrote ${OUTPUT}: ${releases.map((r) => r.name).join(", ")}.`);
